using System;using System.Data;using System.Drawing;using System.Reflection;using System.Windows.Forms;using System.Threading;using System.Threading.Tasks;using System.Collections.Generic;using PharmacyManagement.Application;
class SessionAccessProbe {
static int checks;static BindingFlags ins=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;static BindingFlags stat=BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public;
static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;Console.WriteLine("PASS "+message);}
static void Pump(Task task){var end=DateTime.UtcNow.AddSeconds(10);while(!task.IsCompleted){if(DateTime.UtcNow>end)throw new Exception("pending read timeout");Application.DoEvents();Thread.Sleep(1);}task.GetAwaiter().GetResult();Application.DoEvents();}
[STAThread]static void Main(string[] args){Console.OutputEncoding=System.Text.Encoding.UTF8;Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var a=Assembly.LoadFrom(args[0]);a.GetType("project_fo_3.AppFonts").GetMethod("Initialize",stat,null,Type.EmptyTypes,null).Invoke(null,null);var session=a.GetType("project_fo_3.SessionContext");var start=session.GetMethod("Start",stat);var clear=session.GetMethod("Clear",stat);var formType=a.GetType("project_fo_3.Manufacturer");var fixture=a.GetType("project_fo_3.ResponsiveLayoutSelfTests+PendingManufacturerService");
try{foreach(bool english in new[]{false,true}){start.Invoke(null,new object[]{"supplier-access", "Manager", "SUP-E"});var service=Activator.CreateInstance(fixture,true);using(var f=(Form)Activator.CreateInstance(formType,ins,null,new object[]{false,english,service,true,null,new Func<bool>(()=>false)},null)){
f.ShowInTaskbar=false;f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Size=new Size(1200,800);f.Show();Application.DoEvents();var pending=(List<TaskCompletionSource<IReadOnlyList<ManufacturerRecord>>>)fixture.GetField("Pending",ins).GetValue(service);Check(pending.Count==1,"real form started guarded async read");var record=new ManufacturerRecord{CompId="0007",CompName="مُستَلزمات Pharma 500 mg",CompPhone="+967 077 012 345",CompAddress="عدن Main 12"};pending[0].SetResult(new[]{record});var until=DateTime.UtcNow.AddSeconds(10);var table=(AntdUI.Table)f.Controls.Find("manufacturerTable",true)[0];while(table.RowCount!=1){if(DateTime.UtcNow>until)throw new Exception("initial rows timeout");Application.DoEvents();Thread.Sleep(1);}Application.DoEvents();var access=table.AccessibilityObject;Check(access.GetChildCount()==2,"authenticated context exposes real header and row");var row=access.GetChild(1);var cell=row.GetChild(english?1:2);Check(cell.Value==record.CompName,"current session exact mixed name");
var worker=new Thread(()=>start.Invoke(null,new object[]{"supplier-access","Manager","SUP-E"}));worker.Start();worker.Join();Check(((DataTable)table.DataSource).Rows.Count==1,"queued UI invalidation has not yet cleared source");Check(access.GetChildCount()==0&&row.Name==""&&cell.Value==""&&cell.Bounds.IsEmpty,"same-user relogin denies cached access before queued clear");Application.DoEvents();Check(((DataTable)table.DataSource).Rows.Count==0,"queued session notification clears table");var reload=(Task)formType.GetMethod("ReloadGridAsync",ins).Invoke(f,null);pending[1].SetResult(new[]{record});Pump(reload);Check(access.GetChildCount()==2&&access.GetChild(1).GetChild(english?1:2).Value==record.CompName,"fresh current-session reload restores accessible values");Check(row.Name==""&&cell.Value=="","old accessible objects remain invalid after reload");var fresh=access.GetChild(1).GetChild(english?1:2);worker=new Thread(()=>clear.Invoke(null,null));worker.Start();worker.Join();Check(access.GetChildCount()==0&&fresh.Value==""&&fresh.Bounds.IsEmpty,"logout hides new values before queued clear");Application.DoEvents();Check(((DataTable)table.DataSource).Rows.Count==0,"logout clears source");}}
Console.WriteLine("CHECKS="+checks);}finally{clear.Invoke(null,null);}}
}
